def occurrencesOfElement(nums, queries, x):
    # Step 1: collect the indices of x in increasing order
    positions = [i for i, num in enumerate(nums) if num == x]

    # Step 2: the q-th occurrence (1-indexed) is positions[q - 1], if it exists
    result = []
    for q in queries:
        if q <= len(positions):
            result.append(positions[q - 1])
        else:
            result.append(-1)
    return result
